use super::*;
use std::collections::VecDeque;
pub(super) struct Max {pub open:bool,pub debug:bool,pub snap_objects:bool,pub db:Option<forge_engine::AssetDatabase>,pub frames:VecDeque<f32>,pub memory:sysinfo::System,pub last:Option<std::time::Instant>,pub bytes:Option<u64>}
impl Default for Max{fn default()->Self{Self{open:false,debug:false,snap_objects:false,db:None,frames:VecDeque::new(),memory:sysinfo::System::new(),last:None,bytes:None}}}
pub(super) fn brand(ui:&mut egui::Ui){let(r,_)=ui.allocate_exact_size(egui::vec2(25.,25.),egui::Sense::hover());let p=ui.painter();let c=egui::Color32::from_rgb(95,166,230);let pt=|x:f32,y:f32|r.min+egui::vec2(x,y);for (a,b) in [(pt(2.,3.),pt(9.,23.)),(pt(9.,3.),pt(23.,8.)),(pt(9.,12.),pt(19.,17.))]{p.rect_filled(egui::Rect::from_two_pos(a,b),1.,c);}}
pub(super) fn menu(ui:&mut egui::Ui,e:&mut Editor){ui.checkbox(&mut e.max.open,tr(e.uk,"База ресурсів / профайлер","Asset database / profiler"));ui.checkbox(&mut e.max.debug,tr(e.uk,"Діагностика","Debug"));ui.checkbox(&mut e.max.snap_objects,tr(e.uk,"Прив’язка до об’єктів","Object snapping"));}
pub(super) fn assets(ui:&mut egui::Ui,e:&mut Editor){if ui.button(tr(e.uk,"Імпорт Aseprite JSON","Import Aseprite JSON")).clicked(){if e.path.is_none(){e.save(false);}if let Some(root)=e.path.as_ref().and_then(|p|p.parent()){if let Some(path)=rfd::FileDialog::new().add_filter("Aseprite JSON Array",&["json"]).pick_file(){match forge_engine::import_aseprite(&path,root){Ok(o)=>{e.selected=Some(o.id);e.project.objects.push(o);e.pro.last_scan=None;e.status="Aseprite imported".into();},Err(err)=>e.status=err}}}}}
pub(super) fn windows(ctx:&egui::Context,e:&mut Editor){let dt=ctx.input(|i|i.unstable_dt)*1000.;if dt.is_finite()&&dt>0.{e.max.frames.push_back(dt);if e.max.frames.len()>180{e.max.frames.pop_front();}}if e.max.open||e.master.profiler{let now=std::time::Instant::now();if e.max.last.is_none_or(|t|now.duration_since(t).as_secs()>=1){e.max.last=Some(now);if let Ok(pid)=sysinfo::get_current_pid(){e.max.memory.refresh_processes(sysinfo::ProcessesToUpdate::Some(&[pid]),true);e.max.bytes=e.max.memory.process(pid).map(|p|p.memory());}}let mut open=true;egui::Window::new(tr(e.uk,"Діагностика ресурсів та швидкодії","Assets & performance")).open(&mut open).show(ctx,|ui|{ui.label(format!("Startup to first UI: {:.1} ms",super::FIRST_UI.get().copied().unwrap_or_default()));ui.label(format!("RSS: {}",e.max.bytes.map(|b|format!("{:.1} MiB",b as f64/1048576.)).unwrap_or("N/A".into())));let(r,_)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(160.),100.),egui::Sense::hover());let ceiling=e.max.frames.iter().copied().fold(33.4,f32::max);let pts=e.max.frames.iter().enumerate().map(|(i,&v)|egui::pos2(r.left()+i as f32/179.*r.width(),r.bottom()-v/ceiling*r.height())).collect::<Vec<_>>();if pts.len()>1{ui.painter_at(r).add(egui::Shape::line(pts,egui::Stroke::new(1.5,egui::Color32::LIGHT_GREEN)));}ui.label(format!("Frame {:.1} ms / peak {:.1} ms",dt,ceiling));if ui.button(tr(e.uk,"Оновити базу","Refresh database")).clicked(){if let Some(root)=e.path.as_ref().and_then(|p|p.parent()){match forge_engine::AssetDatabase::refresh(root,&e.pro.assets,&e.project){Ok(db)=>e.max.db=Some(db),Err(err)=>e.status=err}}}if let Some(db)=&e.max.db{egui::ScrollArea::vertical().max_height(220.).show(ui,|ui|{for (path,a) in &db.entries{ui.collapsing(format!("{} · {} refs",path,a.references.len()),|ui|{ui.monospace(a.id.to_string());ui.label(format!("{} bytes · present {}",a.bytes,a.present));for x in &a.references{ui.label(x);}});}});}});if !open{e.max.open=false;e.master.profiler=false;}}
 if e.max.debug{let mut open=true;egui::Window::new(tr(e.uk,"Діагностика гри","Game debug")).open(&mut open).show(ctx,|ui|{let p=e.play.as_ref().unwrap_or(&e.project);ui.label(format!("Simulation: {:.3}s",e.sim.elapsed));ui.checkbox(&mut e.tools.colliders,tr(e.uk,"Колізії","Colliders"));if let Some(o)=p.objects.iter().find(|o|Some(o.id)==e.selected){ui.monospace(format!("{}\nID {}\nX {:.2} Y {:.2}\nAngle {:.2}\nBody {:?}\nClip {}",o.name,o.id,o.position[0],o.position[1],o.rotation,o.body,o.clip_name));}ui.separator();egui::ScrollArea::vertical().max_height(200.).show(ui,|ui|{for event in e.sim.events.iter().rev().take(20){ui.label(event);}for err in e.sim.errors.iter().rev(){ui.colored_label(egui::Color32::LIGHT_RED,err);}});});e.max.debug=open;}}
pub(super) fn snap(e:&mut Editor){if !e.max.snap_objects||e.gizmo!=0||e.drag_start.is_none(){return;}let candidates=e.project.objects.iter().filter(|o|Some(o.id)!=e.selected&&!e.pro.multi.contains(&o.id)).map(|o|o.position).collect::<Vec<_>>();let tolerance=8./e.zoom.max(0.2);for o in e.project.objects.iter_mut().filter(|o|Some(o.id)==e.selected||e.pro.multi.contains(&o.id)){for axis in 0..2{if e.tools.axis!=0&&e.tools.axis!=axis+1{continue;}if let Some(v)=candidates.iter().map(|p|p[axis]).filter(|v|(*v-o.position[axis]).abs()<=tolerance).min_by(|a,b|(*a-o.position[axis]).abs().total_cmp(&(*b-o.position[axis]).abs())){o.position[axis]=v;}}}}

pub(super) fn dock_tabs(ui:&mut egui::Ui,e:&mut Editor){ui.horizontal_wrapped(|ui|{for (i,label) in [tr(e.uk,"Сцена","Scene"),tr(e.uk,"Інспектор","Inspector"),tr(e.uk,"Інструменти","Tools")].iter().enumerate(){let r=ui.add(egui::Label::new(*label).sense(egui::Sense::click_and_drag()));r.dnd_set_drag_payload(i);}ui.separator();for (zone,label) in [tr(e.uk,"Ліворуч","Left"),tr(e.uk,"Праворуч","Right"),tr(e.uk,"Знизу","Bottom"),tr(e.uk,"Зверху","Top")].iter().enumerate(){let r=ui.button(*label);if let Some(i)=r.dnd_release_payload::<usize>(){if *i<3{e.master.settings.dock[*i]=zone;match *i{0=>e.workspace.prefs.scene=false,1=>e.workspace.prefs.inspector=false,_=>e.workspace.prefs.bottom=false};}}}let r=ui.button(tr(e.uk,"Плаваюча","Float"));if let Some(i)=r.dnd_release_payload::<usize>(){match *i{0=>e.workspace.prefs.scene=true,1=>e.workspace.prefs.inspector=true,2=>e.workspace.prefs.bottom=true,_=>{}}}});}
